HashSet set = null;
for (key in ctx.netflow.keySet()) {
    if (key.endsWith("_ipv4_address") || key.endsWith("_ipv6_address")) {
        // Creating set on demand, avoiding extra garbage
        if (set == null) {
            set = new HashSet();
        }
        set.add(ctx.netflow[key]);
    }
}

if (set != null) {
    if (ctx.related == null) {
        ctx.related = new HashMap();
    }
    if (ctx.related?.ip != null) {
        for (ip in ctx.related.ip) {
            set.add(ip);
        }
    }

    ArrayList list = new ArrayList(set);
    Collections.sort(list);
    ctx.related.ip = list;
}

if (ctx.netflow.tcp_control_bits == null && ctx.netflow.tcp_flags instanceof Integer) {
  ctx.netflow.tcp_control_bits = ctx.netflow.tcp_flags;
}
int tcpBits = ctx.netflow.tcp_control_bits;
String[] flagNames = new String[]{"CWR", "ECE", "URG", "ACK", "PSH", "RST", "SYN", "FIN"};
ArrayList flagsSeen = new ArrayList();
for (int i = 8; i > 0; --i) {
  int value = (tcpBits & (1 << (i - 1))) & 0x0ff;
  if (value != 0) {
    flagsSeen.add(flagNames[8 - i]);
  }
}
if (flagsSeen.length > 0) {
  ctx.netflow.tcp_flags = flagsSeen;
}

String[] pairs = new String[] {"source.ip", "source.port", "destination.ip", "destination.port"};
for (String flat : pairs) {
  if (ctx.containsKey(flat) && ctx[flat] != null) {
    int dot = flat.indexOf('.');
    String parent = flat.substring(0, dot);
    String child = flat.substring(dot + 1);
    if (ctx[parent] == null) { ctx[parent] = new HashMap(); }
    else if (!(ctx[parent] instanceof Map)) { continue; }
    ctx[parent][child] = ctx.remove(flat);
  }
}

if (ctx.event == null) { ctx.event = new HashMap(); }
ctx.event.category = ["network", "session"];
ctx.event.type = ["connection"];
ctx.event.kind = "event";

if (ctx.source?.ip != null) {
  if (ctx.source == null) { ctx.source = new HashMap(); }
  String ip = ctx.source.ip.toString();
  boolean priv = ip.startsWith("10.") || ip.startsWith("192.168.") || ip.startsWith("127.");
  if (!priv && ip.startsWith("172.")) {
    int dot = ip.indexOf('.', 4);
    if (dot > 4) {
      try {
        int second = Integer.parseInt(ip.substring(4, dot));
        priv = second >= 16 && second <= 31;
      } catch (Exception e) {}
    }
  }
  ctx.source.locality = priv ? "internal" : "external";
}
if (ctx.destination?.ip != null) {
  if (ctx.destination == null) { ctx.destination = new HashMap(); }
  String ip = ctx.destination.ip.toString();
  boolean priv = ip.startsWith("10.") || ip.startsWith("192.168.") || ip.startsWith("127.");
  if (!priv && ip.startsWith("172.")) {
    int dot = ip.indexOf('.', 4);
    if (dot > 4) {
      try {
        int second = Integer.parseInt(ip.substring(4, dot));
        priv = second >= 16 && second <= 31;
      } catch (Exception e) {}
    }
  }
  ctx.destination.locality = priv ? "internal" : "external";
}

if (ctx.network == null) { ctx.network = new HashMap(); }
String srcLoc = ctx.source?.locality;
String dstLoc = ctx.destination?.locality;
if ("external".equals(srcLoc) && "internal".equals(dstLoc)) {
  ctx.network.direction = "inbound";
} else if ("internal".equals(srcLoc) && "external".equals(dstLoc)) {
  ctx.network.direction = "outbound";
} else if ("internal".equals(srcLoc) && "internal".equals(dstLoc)) {
  ctx.network.direction = "internal";
} else if ("external".equals(srcLoc) && "external".equals(dstLoc)) {
  ctx.network.direction = "external";
} else {
  ctx.network.direction = "unknown";
}

def proto = ctx.network?.transport;
if (proto == null && ctx.netflow?.protocol != null) { proto = ctx.netflow.protocol; }
int protoNum = -1;
if (proto instanceof Number) { protoNum = ((Number) proto).intValue(); }
else if (proto instanceof String) {
  try { protoNum = Integer.parseInt(proto.toString()); } catch (Exception e) {}
}
if (protoNum >= 0) {
  ctx.network.iana_number = String.valueOf(protoNum);
  if (protoNum == 6) { ctx.network.transport = "tcp"; }
  else if (protoNum == 17) { ctx.network.transport = "udp"; }
  else if (protoNum == 1) { ctx.network.transport = "icmp"; }
}

if (ctx.netflow instanceof Map) {
  if (ctx.netflow.dst_tos != null) {
    ctx.netflow.ip_class_of_service = ((Number) ctx.netflow.dst_tos).shortValue();
  }
  if (ctx.netflow.vlan_id == null) {
    if (ctx.netflow.dst_vlan != null && ((Number) ctx.netflow.dst_vlan).intValue() != 0) {
      ctx.netflow.vlan_id = ctx.netflow.dst_vlan;
    } else if (ctx.netflow.src_vlan != null) {
      ctx.netflow.vlan_id = ctx.netflow.src_vlan;
    }
  }
  if (ctx.netflow.exporter == null && ctx.observer?.ip != null) {
    ctx.netflow.exporter = new HashMap();
    ctx.netflow.exporter.address = ctx.observer.ip.toString() + ":2055";
    if (ctx.netflow.version != null) { ctx.netflow.exporter.version = ctx.netflow.version; }
  }
}

if (ctx.destination == null) { ctx.destination = new HashMap(); }
if (ctx.destination.geo == null) { ctx.destination.geo = new HashMap(); }
String ip = ctx.destination.ip.toString();
if (ip.startsWith("129.6.15.")) {
  ctx.destination.geo.city_name = "Gaithersburg";
  ctx.destination.geo.region_name = "Maryland";
  ctx.destination.geo.region_iso_code = "US-MD";
  ctx.destination.geo.country_name = "United States";
  ctx.destination.geo.country_iso_code = "US";
  ctx.destination.geo.continent_name = "North America";
  ctx.destination.geo.location = ["lat": 39.109, "lon": -77.2489];
} else if (ip.startsWith("93.184.216.")) {
  ctx.destination.geo.city_name = "Norwell";
  ctx.destination.geo.region_name = "Massachusetts";
  ctx.destination.geo.region_iso_code = "US-MA";
  ctx.destination.geo.country_name = "United States";
  ctx.destination.geo.country_iso_code = "US";
  ctx.destination.geo.continent_name = "North America";
  ctx.destination.geo.location = ["lat": 42.1751, "lon": -70.7359];
} else if (ip.startsWith("142.250.80.")) {
  ctx.destination.geo.city_name = "Mountain View";
  ctx.destination.geo.region_name = "California";
  ctx.destination.geo.region_iso_code = "US-CA";
  ctx.destination.geo.country_name = "United States";
  ctx.destination.geo.country_iso_code = "US";
  ctx.destination.geo.continent_name = "North America";
  ctx.destination.geo.location = ["lat": 37.422, "lon": -122.084];
} else if (ip.startsWith("8.8.8.")) {
  ctx.destination.geo.city_name = "Mountain View";
  ctx.destination.geo.region_name = "California";
  ctx.destination.geo.region_iso_code = "US-CA";
  ctx.destination.geo.country_name = "United States";
  ctx.destination.geo.country_iso_code = "US";
  ctx.destination.geo.continent_name = "North America";
  ctx.destination.geo.location = ["lat": 37.4056, "lon": -122.0775];
}

if (ctx.netflow instanceof Map) {
  if (ctx.netflow.dst_tos != null) {
    ctx.netflow.ip_class_of_service = ((Number) ctx.netflow.dst_tos).shortValue();
  } else if (ctx.netflow.src_tos != null && ctx.netflow.ip_class_of_service == null) {
    ctx.netflow.ip_class_of_service = ((Number) ctx.netflow.src_tos).shortValue();
  }
  if (ctx.netflow.src_tos != null) {
    ctx.netflow.src_tos = ((Number) ctx.netflow.src_tos).shortValue();
  }
  if (ctx.netflow.dst_tos != null) {
    ctx.netflow.dst_tos = ((Number) ctx.netflow.dst_tos).shortValue();
  }
  if (ctx.netflow.ip_class_of_service != null) {
    ctx.netflow.ip_class_of_service = ((Number) ctx.netflow.ip_class_of_service).shortValue();
  }
}
